-- Пул канала «Здоровый Взрослый»: твёрдость взрослого (аудит теории #1349). В пуле почти не было
-- фраз, где взрослый ставит рамку Импульсивному и Недисциплинированному Ребёнку; плюс род читателя в двух фразах.
-- Идемпотентно: UPDATE по старому тексту, INSERT только отсутствующих. "updatedAt" — NOT NULL без DEFAULT.
UPDATE "HealthyAdultPhrase" SET "text" = 'Кто-то однажды упрекнул тебя в «излишней чувствительности». Ближе к делу — это способность замечать то, что другие проскакивают. У неё есть цена. Поломки в этом нет.', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Кто-то однажды назвал тебя «слишком чувствительным». Ближе к делу — это способность замечать то, что другие проскакивают. У неё есть цена. Поломки в этом нет.';
UPDATE "HealthyAdultPhrase" SET "text" = 'Сегодня можно приготовить ужин из того, что нашлось, и не называть это «я совсем за собой не слежу».', "updatedAt" = CURRENT_TIMESTAMP
 WHERE "text" = 'Сегодня можно приготовить ужин из того, что нашлось, и не называть это «я совсем себя запустил».';

INSERT INTO "HealthyAdultPhrase" ("text", "sortOrder", "updatedAt")
SELECT seed."column1", seed."column2", CURRENT_TIMESTAMP FROM (VALUES
  ('Палец уже над кнопкой «оформить заказ», а внутри знакомое «срочно, сейчас, иначе не выдержу». Давай подождём до утра. Если и утром это будет нужно, купим. Я не запрещаю, я просто не даю тревоге решать за тебя.', 160),
  ('Скучно, и хочется бросить на середине. Понимаю. Давай договоримся: ещё двадцать минут, потом перерыв. Мне не нужно, чтобы вышло идеально. Мне важно, чтобы у тебя был опыт: скучное тоже доводится до конца.', 161),
  ('Час ночи, и лента обещает, что после ещё одного видео станет легче. Не станет, и ты это знаешь. Телефон отправляется на тумбочку. Это не наказание: завтрашнему тебе сон нужнее, чем ещё одно видео.', 162),
  ('Хочется написать ему всё, что думаешь, прямо сейчас. Злость имеет право быть. А отправлять её в чат в таком виде я не дам. Напиши в заметки, перечитай утром, и тогда решим, что из этого правда нужно сказать вслух.', 163),
  ('Отдых и бегство снаружи похожи, а внутри разные. После отдыха к делу вернуться легче, после бегства труднее. Письмо не пишется уже неделю. Пять минут на него, а потом отдыхай по-настоящему.', 164),
  ('Забота иногда звучит как «нет»: не сейчас, не так, не в третий раз за вечер.', 165),
  ('Обещание себе лечь до полуночи тоже обещание. Его можно сдержать не из страха, а из уважения к тому, кто завтра проснётся.', 166),
  ('Резкое слово уже сказано. Стыдиться всю ночь не нужно, делать вид, что ничего не было, тоже. Завтра можно подойти и сказать: «Мне жаль, что так получилось. Давай поговорим по-другому».', 167),
  ('Хочется, чтобы все подстроились: тебе сейчас тяжелее всех. Тебе правда тяжело, я это вижу. И у других людей тоже есть свой предел. Можно просить о помощи и при этом слышать их «не могу».', 168),
  ('Деньги на этот месяц уже расписаны, а внутри поднимается «я заслуживаю хоть что-то хорошее». Заслуживаешь. Давай найдём хорошее, которое не придётся отрабатывать весь следующий месяц: прогулку, ванну, звонок другу.', 169),
  ('Начинать новое всегда приятнее, чем заканчивать старое. Сегодня новое подождёт. Сначала доделаем то, что уже на столе, а потом посмотрим, на что останутся силы.', 170),
  ('Рамка тоже забота: она держит, когда держаться в одиночку трудно.', 171)
) AS seed
WHERE NOT EXISTS (
  SELECT 1 FROM "HealthyAdultPhrase" p WHERE p."text" = seed."column1"
);
